const PAGE_IDS=Object.fromEntries(Object.entries(PATHS).map(([k,v])=>[v,k]));PAGE_IDS['/linebet-promo-code']='promolinebet';
const UI=key=>I18N[lang][key]??I18N.fr[key]??key;const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];let lang=localStorage.getItem('btts-meta-lang')||'fr';let page='home';let SNAP=null;
