function pageHeader(){let key=titleMap()[page]||'home';$('#pageTitle').textContent=UI('page_'+key);$('#pageDescription').textContent=UI('desc_'+key);$('#crumb').textContent=UI('page_'+key);$('#pageEyebrow').textContent=page==='home'?'FOOTBALL INTELLIGENCE':`${UI('nav_insights')} / ${UI('page_'+key)}`;$('.page-intro').dataset.market=page;$('.page-intro').classList.toggle('market-page',['btts','over','scores'].includes(page));$('#pageActions').innerHTML=['home','btts','over','combined','scores'].includes(page)?`<a class="button secondary small" href="#${PATHS.method}">⌘ ${UI('go_method')}</a>`:''}
function marketChip(label,color){return `<span class="market-chip ${color}"><i class="market-dot" aria-hidden="true"></i>${label}</span>`}
function filtersRow(){return `<div class="filter-row" aria-label="${UI('filters')}"><button class="filter-pill active" type="button">${UI('period_today')}</button><button class="filter-pill" type="button">${UI('period_tomorrow')}</button><button class="filter-pill" type="button">${UI('period_week')}</button><span class="filter-separator"></span><button class="filter-pill active" type="button">${UI('all_matches')}</button><select class="filter-select" aria-label="${UI('all_competitions')}"><option>${UI('all_competitions')}</option></select></div>`}
function metricStrip(){return `<div class="metric-strip"><div class="metric-card"><div class="metric-label">${UI('metric_fixtures')}</div><div class="metric-value metric-unavailable">—</div><div class="metric-note">${UI('no_live')}</div></div><div class="metric-card"><div class="metric-label">${UI('metric_snapshot')}</div><div class="metric-value" style="font-size:16px">${UI('snapshot_date')}</div><div class="metric-note">${UI('data_unavailable')}</div></div><div class="metric-card"><div class="metric-label">${UI('metric_markets')}</div><div class="metric-value">3</div><div class="metric-note">${UI('free_markets')}</div></div></div>`}
function emptyState(title=UI('fixtures_empty'),desc=UI('fixtures_empty_detail')){return `<div class="empty-state"><span class="empty-icon" aria-hidden="true">⌕</span><h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`}
function matchTemplate(kind='btts'){const color=kind==='over'?'blue':kind==='scores'?'violet':'teal';return `<div class="template-label">${UI('card_template')}</div><article class="match-card" style="--market:var(--${color})"><div class="match-top"><div class="competition-line"><span class="competition-symbol">◎</span>${UI('competition')}</div><span class="match-status">${UI('data_unavailable')}</span></div><div class="match-body"><div class="teams"><div class="team-row"><span class="team-crest">·</span><span class="team-label">${UI('team_home')}</span></div><div class="team-row"><span class="team-crest">·</span><span class="team-label">${UI('team_away')}</span></div></div><div class="match-time"><span class="time-placeholder ltr" dir="ltr">${UI('time_unavailable')}</span><span class="time-note">${UI('source_not_loaded')}</span></div></div><div class="match-bottom"><div class="probability-row" style="--market:var(--teal)"><span class="prob-label">${UI('market_btts')}</span><span class="prob-track"><span></span></span><span class="prob-value">—</span></div><div class="probability-row" style="--market:var(--blue)"><span class="prob-label">${UI('market_over')}</span><span class="prob-track"><span></span></span><span class="prob-value">—</span></div><div class="source-caption"><i class="source-dot"></i>${UI('source_not_loaded')} · <a href="#${PATHS.match}">${UI('open_detail')} ↗</a></div></div></article>`}
