function fmtPct(n){return `${new Intl.NumberFormat(lang==='ar'?'ar':lang==='en'?'en':'fr',{maximumFractionDigits:1}).format(n)}%`}
function metricCard(label,value,detail){return `<div class="fact-card"><span class="fact-label">${label}</span><strong class="fact-value ltr" dir="ltr">${value}</strong><span class="fact-detail">${detail}</span></div>`}
function chartRow(label,total,won,loss,rate){let wonWidth=(won/total*100).toFixed(2);return `<div class="chart-row"><span class="chart-row-label">${label}</span><span class="chart-track" role="img" aria-label="${label}: ${won} ${UI('legend_won')}, ${loss} ${UI('legend_lost')}"><i class="chart-won" style="display:block;width:${wonWidth}%"></i></span><span class="chart-values"><b>${fmtPct(rate)}</b> · ${fmtInt(won)} ${UI('legend_won')} / ${fmtInt(loss)} ${UI('legend_lost')}</span></div>`}
function statsPage(){let s=SNAP.stats;let p=SNAP.trackingPeriod;return `${sourceBanner()}<div class="fact-grid">${metricCard(UI('overall_rate'),fmtPct(s.rate),`${fmtInt(s.won)} ${UI('won')} / ${fmtInt(s.lost)} ${UI('lost')} · ${fmtInt(s.total)} ${UI('settled_count')}`)}${metricCard(UI('settled'),fmtInt(s.total),`${fmtInt(s.won)} ${UI('positive')} · ${fmtInt(s.lost)} ${UI('negative')}`)}${metricCard(UI('period'),`${p.from.slice(8,10)}.08–${p.to.slice(8,10)}.11.26`,`${UI('archive_title')} · ${UI('source_esn')}`)}</div><section class="chart-panel"><h2 class="chart-title">${UI('chart_title')}</h2><p class="chart-sub">${UI('chart_period')}</p><div class="chart-legend"><span><i class="legend-square" style="background:var(--green)"></i>${UI('legend_won')}</span><span><i class="legend-square" style="background:var(--red)"></i>${UI('legend_lost')}</span></div>${chartRow(UI('market_btts_name'),s.byType.btts.total,s.byType.btts.won,s.byType.btts.lost,s.byType.btts.rate)}${chartRow(UI('market_over_name'),s.byType.over25.total,s.byType.over25.won,s.byType.over25.lost,s.byType.over25.rate)}<div class="data-period" style="margin-top:12px">${UI('exact_data_empty')}</div></section><div class="data-warning" style="margin-top:12px"><span class="warning-symbol">!</span><span>${UI('tracking_caveat')}</span></div><div class="panel rail-card" style="margin-top:12px"><h3 class="rail-title">${UI('other_states')}</h3><div class="status-legend"><span class="status-badge warn">${UI('pending_count')}: <b>${fmtInt(s.pending)}</b></span><span class="status-badge">${UI('unverifiable_count')}: <b>${fmtInt(s.unverifiable)}</b></span></div><p class="micro muted" style="margin:0">${UI('not_in_rate')}.</p></div>`}
function statusChip(status){let good=status==='WON';return `<span class="result-status ${good?'won':'lost'}"><i class="status-shape">${good?'✓':'×'}</i>${UI(good?'status_won':'status_lost')}</span>`}
function archiveRecord(r){const market=r.market==='over25'?UI('market_over_name'):UI('market_btts_name');const yesNo=r.prediction==='Oui'? (lang==='en'?'Yes':lang==='ar'?'نعم':'Oui'):(lang==='en'?'No':lang==='ar'?'لا':'Non');const date=lang==='en'?'02 Nov 2026':lang==='ar'?'02 نوفمبر 2026':'02 nov. 2026';return `<article class="archive-record"><time class="archive-date ltr" dir="ltr">${date}</time><div class="archive-match"><strong>${esc(r.match)}</strong><small>${esc(r.league)}</small></div><div class="archive-market"><b>${market}</b>${UI('selection')}: ${yesNo} · ${UI('actual_score')}: <span class="ltr" dir="ltr">${esc(r.finalScore)}</span></div><div class="archive-prob"><b>${fmtPct(r.probability)} · ${UI('recorded_estimate')}</b><small>${UI('source_verified')}</small></div>${statusChip(r.status)}</article>`}
function resultsPage(){return `${sourceBanner()}<div class="section-heading" style="margin-top:13px"><div><h2>${UI('results_archive')}</h2><p>${UI('results_period')}</p></div></div><div class="status-legend"><span class="status-badge good">✓ ${UI('status_won')}</span><span class="status-badge bad">× ${UI('status_lost')}</span><span class="status-badge">${UI('verified')}</span></div><div class="panel">${SNAP.records.map(archiveRecord).join('')}</div>`}
function matchPage(){let a=SNAP.records[0],b=SNAP.records[1];return `${sourceBanner()}<article class="panel match-detail-card" style="margin-top:13px"><header class="detail-head"><div><span class="archive-stamp">${UI('detail_archive')}</span><h2 class="detail-title">${UI('match_label')}</h2><div class="detail-league">${UI('match_league')} · ${UI('match_date')}</div></div><div class="score-final ltr" dir="ltr">${UI('match_score')}</div></header><div class="detail-teams"><span class="detail-team ltr" dir="ltr">Atalanta</span><span class="score-final ltr" dir="ltr">${UI('match_score')}</span><span class="detail-team ltr" dir="ltr">Parma</span></div><section class="detail-outcome"><div class="detail-outcome-head">${marketChip(UI('market_btts_name'),'teal')}${statusChip(a.status)}</div><div class="detail-meta"><span>${UI('detail_prediction')}: <b>${a.prediction}</b></span><span>${UI('recorded_estimate')}: <b class="ltr" dir="ltr">${fmtPct(a.probability)}</b></span><span>${UI('actual_score')}: <b class="ltr" dir="ltr">${a.finalScore}</b></span></div><div class="detail-source">${UI('detail_market_note')}</div></section><section class="detail-outcome" style="margin-top:9px"><div class="detail-outcome-head">${marketChip(UI('market_over_name'),'blue')}${statusChip(b.status)}</div><div class="detail-meta"><span>${UI('detail_prediction')}: <b>${b.prediction}</b></span><span>${UI('recorded_estimate')}: <b class="ltr" dir="ltr">${fmtPct(b.probability)}</b></span><span>${UI('actual_score')}: <b class="ltr" dir="ltr">${b.finalScore}</b></span></div><div class="detail-source">${UI('detail_market_note')}</div></section><p class="detail-source">${UI('detail_source_note')} ${UI('snapshot_asof')}</p></article>`}
function vipPage(){return `<div class="vip-hero"><div class="vip-emblem"><span class="vip-lock">◇</span>${UI('VIP_badge')}</div><h2>${UI('VIP_head')}</h2><p>${UI('VIP_text')}</p></div><div class="partner-links"><a href="#${PATHS.promo1xbet}"><span>${UI('VIP_partner1')}</span><b>↗</b></a><a href="#${PATHS.promolinebet}"><span>${UI('VIP_partner2')}</span><b>↗</b></a></div><div class="vip-steps"><div class="step-card"><span class="step-index">01</span><strong>${UI('VIP_step1')}</strong><p>${UI('VIP_new')}</p></div><div class="step-card"><span class="step-index">02</span><strong>${UI('VIP_step2')}</strong><p>${UI('VIP_code_page')} ${UI('VIP_deposit')}</p></div><div class="step-card"><span class="step-index">03</span><strong>${UI('VIP_step3')}</strong><p>${UI('VIP_manual')} · ${UI('VIP_coupon')}</p></div></div><div class="locked-quiet" style="margin-top:12px"><strong>◇ ${UI('VIP_private_title')}</strong>${UI('VIP_private_text')}</div><div class="data-warning" style="margin-top:12px"><span class="warning-symbol">i</span><span>${UI('VIP_noid')} ${UI('VIP_approval')} ${UI('VIP_noresults')}</span></div>`}
const PARTNERS={promo1xbet:{name:'partner_1xbet',code:'vipbtts'},promolinebet:{name:'partner_linebet',code:'VISION221'},promomelbet:{name:'partner_melbet',code:'Bttswin'},promo888:{name:'partner_888',code:'btts221'},promo888alias:{name:'partner_888',code:'btts221'}};
function promoPage(){let p=PARTNERS[page];return `<div class="promo-confirmed"><strong class="promo-percent ltr" dir="ltr">${UI('promo_bonus')}</strong><p>${UI('promo_worldwide')}</p></div><section class="panel panel-pad"><span class="section-kicker">${UI('nav_promo')} · ${UI(p.name)}</span><h2 style="font:700 20px var(--font-head);margin:9px 0 5px">${UI(p.name)}</h2><p class="subtle micro">${UI('promo_check')}</p><div class="promo-code"><span>${UI('promo_code_label')}</span><b class="ltr" dir="ltr">${p.code}</b><button class="button ghost small copy-code" type="button" data-code="${p.code}">${UI('copy')}</button></div><div class="rail-note" style="margin-top:12px">${UI('promo_notice')}</div><p class="detail-source" style="margin-top:13px">${UI('promo_check')}</p></section>`}
function methodologyPage(){const rows=[['method_model','method_model_text'],['method_sources','method_sources_text'],['method_limits','method_limits_text'],['method_estimate','method_estimate_text']];return `<div class="panel content-prose">${rows.map(([a,b])=>`<section class="prose-section"><h3>${UI(a)}</h3><p>${UI(b)}</p></section>`).join('')}</div>`}
function otherPage(){if(page==='guide')return `<div class="panel content-prose"><section class="prose-section"><h3>${UI('page_guide')}</h3><p>${UI('guide_def')}</p></section><section class="prose-section"><h3>${UI('method_estimate')}</h3><p>${UI('guide_limit')}</p></section></div>`;let key=page==='terms'?'terms_text':page==='privacy'?'privacy_text':page==='legal'?'legal_text':'responsible_text';return `<div class="panel content-prose"><section class="prose-section"><h3>${UI('page_'+page)}</h3><p>${UI(key)}</p></section>${page==='responsible'?'<span class="archive-stamp">18+</span>':''}<div class="data-warning" style="margin-top:13px"><span class="warning-symbol">i</span><span>${UI('legal_notice')}</span></div></div>`}
function content(){if(!SNAP)return `<div class="empty-state"><h3>${UI('archive_title')}</h3><p>${UI('source_not_loaded')}</p></div>`;if(page==='home')return homePage();if(page==='btts'||page==='over'||page==='scores'||page==='tomorrow')return predictionPage(page==='tomorrow'?'btts':page);if(page==='combined')return combinedPage();if(page==='stats')return statsPage();if(page==='results'||page==='history')return resultsPage();if(page==='match')return matchPage();if(page==='vip')return vipPage();if(PARTNERS[page])return promoPage();if(page==='method')return methodologyPage();return otherPage()}
function rail(){const markets=`<div class="panel rail-card"><h3 class="rail-title">${UI('rail_markets')}</h3><p class="rail-subtitle">${UI('rail_markets_note')}</p><div class="market-list"><div class="market-list-item" style="--market:var(--teal)"><i class="color-bar"></i>BTTS</div><div class="market-list-item" style="--market:var(--blue)"><i class="color-bar"></i>Over 2.5</div><div class="market-list-item" style="--market:var(--violet)"><i class="color-bar"></i>${UI('market_scores')}</div></div></div>`;const sources=`<div class="panel rail-card"><h3 class="rail-title">${UI('rail_sources')}</h3><div class="source-legend"><div class="legend-line"><i class="legend-mark verified"></i>${UI('rail_real')}</div><div class="legend-line"><i class="legend-mark estimate"></i>${UI('rail_estimate')}</div><div class="legend-line"><i class="legend-mark"></i>${UI('rail_missing')}</div></div></div>`;const links=`<div class="panel rail-card"><h3 class="rail-title">${UI('nav_information')}</h3><a class="rail-link" href="#${PATHS.method}">${UI('rail_method')} <span>↗</span></a><a class="rail-link" href="#${PATHS.results}">${UI('rail_results')} <span>↗</span></a><a class="rail-link" href="#${PATHS.vip}">${UI('rail_vip')} <span>↗</span></a></div>`;let stamp=`<div class="rail-note">${UI('snapshot_asof')}<br>${UI('source_esn')}</div>`;if(page==='vip')return `${sources}${markets}${links}`;if(PARTNERS[page])return `${sources}${markets}${stamp}`;return `${markets}${sources}${links}${stamp}`}
function render(){trStatic();pageHeader();$('#pageContent').innerHTML=content();$('#rightRail').innerHTML=rail();$$('.sidebar .nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));let bottom=page==='home'?'home':page==='vip'?'vip':page==='stats'?'stats':page==='results'||page==='history'?'results':'btts';$$('.bottom-nav [data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===bottom));const cb=$('#comboBuilder');if(cb){if(window.matchMedia('(min-width: 901px)').matches)cb.open=true;cb.addEventListener('toggle',()=>{$('.expand-pill',cb).textContent=cb.open?UI('combo_collapse'):UI('combo_expand')});$('.expand-pill',cb).textContent=cb.open?UI('combo_collapse'):UI('combo_expand')};$$('.copy-code').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.code);b.textContent=UI('copied');setTimeout(()=>b.textContent=UI('copy'),1400)}catch{b.textContent=b.dataset.code}}));$$('[data-action="scroll-filters"]').forEach(b=>b.addEventListener('click',()=>$('.filter-row')?.scrollIntoView({behavior:'smooth',block:'center'})))}
$$('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;localStorage.setItem('btts-meta-lang',lang);render()}));window.addEventListener('hashchange',()=>{page=routeFromHash();if(location.hash==='#/linebet-promo-code'){location.hash='#/code-promo-linebet-senegal';return}render();window.scrollTo({top:0,behavior:'smooth'})});$('#collapseToggle').addEventListener('click',()=>{let shell=$('.app-shell');shell.classList.toggle('nav-collapsed');$('#collapseToggle').setAttribute('aria-label',shell.classList.contains('nav-collapsed')?UI('menu_open'):UI('menu_close'))});function closeMobileMenu(){$('.app-shell').classList.remove('mobile-menu-open');$('#mobileBackdrop').style.opacity='0';$('#mobileBackdrop').style.visibility='hidden';$('#menuToggle').setAttribute('aria-expanded','false')};function openMobileMenu(){$('.app-shell').classList.add('mobile-menu-open');$('#mobileBackdrop').style.opacity='1';$('#mobileBackdrop').style.visibility='visible';$('#menuToggle').setAttribute('aria-expanded','true')};$('#menuToggle').addEventListener('click',openMobileMenu);$('#mobileMore').addEventListener('click',openMobileMenu);$('#mobileBackdrop').addEventListener('click',closeMobileMenu);$$('.sidebar .nav-link').forEach(a=>a.addEventListener('click',closeMobileMenu));
fetch('./data-snapshot.json').then(r=>{if(!r.ok)throw new Error('snapshot unavailable');return r.json()}).then(d=>{SNAP=d;window.__APP_READY=true;page=routeFromHash();render()}).catch(()=>{window.__APP_READY=true;render()});page=routeFromHash();render();
